            m["rho"] = {"value": rho, "ci_95": rho_ci}

            tau = safe_kendall(sig_vals, f1_arr)
            m["tau"] = {"value": tau}

            auroc = safe_auroc(sig_vals, binary_correct)
            auroc_ci = bootstrap_metric(safe_auroc, sig_vals, binary_correct.astype(float))
            m["AUROC"] = {"value": auroc, "ci_95": auroc_ci}

            ece_conf = normalize_for_ece(sig_name, sig_vals)
            m["ECE"] = {"value": compute_ece(ece_conf, binary_correct)}

            metrics[sig_name] = m
            print(f"  {sig_name:>12}: rho={rho:.4f}  AUROC={auroc:.4f}  tau={tau:.4f}  ECE={m['ECE']['value']:.4f}")

        split_results["metrics"] = metrics
        results[split_name] = split_results

    # Save
    def json_default(obj):
        if isinstance(obj, (np.floating, np.float64, np.float32)):
            return float(obj)
        if isinstance(obj, (np.integer, np.int64, np.int32)):
            return int(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, np.bool_):
            return bool(obj)
        return str(obj)

    with open(OUTPUT_PATH, "w") as f:
        json.dump(results, f, indent=2, default=json_default)
    print(f"\nSaved to {OUTPUT_PATH}")


if __name__ == "__main__":
    main()
